changeSet.sql:
ALTER TABLE clinlims.his_result_outbox ADD CONSTRAINT chk_his_result_outbox_status
CHECK (status IN ('PENDING','FAILED','ACKNOWLEDGED','DEAD_LETTER','CLOSED'));
ALTER TABLE clinlims.his_result_outbox ADD CONSTRAINT chk_his_result_outbox_event
CHECK (event_type IN ('RESULT','REPORT','AMENDMENT','WITHDRAWAL'));
ALTER TABLE clinlims.his_result_outbox ADD CONSTRAINT chk_his_result_outbox_attempts
CHECK (attempt_count >= 0 AND max_attempts BETWEEN 1 AND 20);
ALTER TABLE clinlims.his_result_outbox ADD CONSTRAINT chk_his_result_outbox_hash
CHECK (payload_hash ~ '^[0-9a-f]{64}$');
ALTER TABLE clinlims.his_result_outbox ADD CONSTRAINT chk_his_result_outbox_close
CHECK (status <> 'CLOSED' OR length(btrim(close_reason)) > 0);

CREATE OR REPLACE FUNCTION clinlims.freeze_his_result_outbox_evidence()
RETURNS trigger AS $body$
BEGIN
    IF NEW.source_system IS DISTINCT FROM OLD.source_system
       OR NEW.business_id IS DISTINCT FROM OLD.business_id
       OR NEW.event_type IS DISTINCT FROM OLD.event_type
       OR NEW.idempotency_key IS DISTINCT FROM OLD.idempotency_key
       OR NEW.payload IS DISTINCT FROM OLD.payload
       OR NEW.payload_hash IS DISTINCT FROM OLD.payload_hash
       OR NEW.created_at IS DISTINCT FROM OLD.created_at THEN
        RAISE EXCEPTION 'HIS result outbox evidence is immutable' USING ERRCODE = '55000';
    END IF;
    RETURN NEW;
END;
$body$ LANGUAGE plpgsql;

CREATE TRIGGER trg_freeze_his_result_outbox_evidence
BEFORE UPDATE ON clinlims.his_result_outbox
FOR EACH ROW EXECUTE FUNCTION clinlims.freeze_his_result_outbox_evidence();
